if ((#ContactSensor #MeetingRoom).contactSensor_contact == false) {
if (triggered == false) {
(#LevelControl #MeetingRoom).light_moveToBrightness(100.0, 0.0)
        delay(10 SEC)
(#LevelControl #MeetingRoom).light_moveToBrightness(0.0, 0.0)
        triggered = true
}
}
else {
triggered = false
}

